svg.desc:
// clk / rst_n go to every instance (not drawn). No glue logic: every net is one child port or one top port.
// Pin label = child port; label at the far end of a short wire = net name; nets with the same label are connected.
// Debug outputs left open: u_lowpapr.phase_n, u_lowpapr.phase_l_abs, u_mod_cand.cand_phase, u_rx_inverse.d_n_re.
[u_ctrl]
pucch_f1_ctrl u_ctrl (.cfg_valid(cfg_valid), .cfg_m_bit(cfg_m_bit), .cfg_nsymb(cfg_nsymb), .cfg_start_symbol(cfg_start_symbol), .cfg_intra_slot_hopping(cfg_intra_slot_hopping), .cfg_group_hopping_mode(cfg_group_hopping_mode), .cfg_n_id(cfg_n_id), .cfg_m0(cfg_m0), .cfg_occ_i(cfg_occ_i), .cfg_slot_idx(cfg_slot_idx), .y_valid(y_valid), .y_sample_q(y_sample_q), .y_first(y_first), .y_last(y_last), .res_ready(res_ready), .gen_ready(gen_ready), .lut_err(lut_err), .phase_valid(phase_valid), .phase_sample_q(phase_sample_q), .phase_first(phase_first), .phase_last(phase_last), .occ_err(occ_err), .acc_done(acc_done), .num_err(num_err), .d_valid(d_valid), .d_ready(d_ready), .tbl_valid(tbl_valid), .cand_err(cand_err), .mle_valid(mle_valid), .mle_candidate_idx(mle_candidate_idx), .mle_uci_bits(mle_uci_bits), .mle_d_rx_i(mle_d_rx_i), .mle_d_rx_q(mle_d_rx_q), .mle_metric_best(mle_metric_best), .mle_metric_second(mle_metric_second), .mle_metric_gap(mle_metric_gap), .cfg_ready(cfg_ready), .busy(busy), .y_ready(y_ready), .res_valid(res_valid), .res_error(res_error), .res_error_code(res_error_code), .res_m_bit(res_m_bit), .res_candidate_idx(res_candidate_idx), .res_uci_bits(res_uci_bits), .res_d_rx_i(res_d_rx_i), .res_d_rx_q(res_d_rx_q), .res_metric_best(res_metric_best), .res_metric_second(res_metric_second), .res_metric_gap(res_metric_gap), .m_bit(m_bit), .n_id(n_id), .gh_mode(gh_mode), .slot_idx(slot_idx), .start_symbol(start_symbol), .hopping(hopping), .m0(m0), .occ_i(occ_i), .n_re(n_re), .n_sf0(n_sf0), .n_sf1(n_sf1), .txn_start(txn_start), .txn_clr(txn_clr), .phase_ready(phase_ready), .join_fire(join_fire));
[u_lowpapr]
pucch_f1_lowpapr_phase_gen u_lowpapr (.txn_start(txn_start), .txn_clr(txn_clr), .n_id(n_id), .gh_mode(gh_mode), .slot_idx(slot_idx), .start_symbol(start_symbol), .hopping(hopping), .m0(m0), .n_sf0(n_sf0), .n_re(n_re), .phase_ready(phase_ready), .gen_ready(gen_ready), .lut_err(lut_err), .phase_valid(phase_valid), .r_phase(r_phase), .phase_sample_q(phase_sample_q), .phase_hop(phase_hop), .phase_m(phase_m), .phase_n(), .phase_l_abs(), .phase_first(phase_first), .phase_last(phase_last));
[u_mod_cand]
pucch_f1_mod_candidates u_mod_cand (.txn_start(txn_start), .txn_clr(txn_clr), .m_bit(m_bit), .cand_ready(cand_ready), .cand_valid(cand_valid), .cand_mask(cand_mask), .cand_m_bit(cand_m_bit), .cand_i(cand_i), .cand_q(cand_q), .cand_phase(), .cand_bits(cand_bits));
[u_rx_inverse]
pucch_f1_rx_inverse u_rx_inverse (.txn_clr(txn_clr), .join_fire(join_fire), .y_i(y_i), .y_q(y_q), .r_phase(r_phase), .phase_sample_q(phase_sample_q), .phase_hop(phase_hop), .phase_m(phase_m), .phase_first(phase_first), .phase_last(phase_last), .occ_i(occ_i), .n_sf0(n_sf0), .n_sf1(n_sf1), .n_re(n_re), .d_ready(d_ready), .occ_err(occ_err), .acc_done(acc_done), .num_err(num_err), .d_valid(d_valid), .d_i(d_i), .d_q(d_q), .d_n_re());
[u_mle]
pucch_f1_scalar_mle u_mle (.txn_clr(txn_clr), .m_bit(m_bit), .cand_valid(cand_valid), .cand_mask(cand_mask), .cand_m_bit(cand_m_bit), .cand_i(cand_i), .cand_q(cand_q), .cand_bits(cand_bits), .d_valid(d_valid), .d_i(d_i), .d_q(d_q), .cand_ready(cand_ready), .tbl_valid(tbl_valid), .cand_err(cand_err), .d_ready(d_ready), .mle_valid(mle_valid), .mle_candidate_idx(mle_candidate_idx), .mle_uci_bits(mle_uci_bits), .mle_d_rx_i(mle_d_rx_i), .mle_d_rx_q(mle_d_rx_q), .mle_metric_best(mle_metric_best), .mle_metric_second(mle_metric_second), .mle_metric_gap(mle_metric_gap));
